CREATE OR REPLACE FUNCTION public.reapply_lead_campaign_rules() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.leads SET category=NEW.category, campaign_name=NEW.campaign_name WHERE tag_origem::text=NEW.platform AND COALESCE(meta_campaign_id,utm_campaign)=NEW.campaign_key AND NEW.active; RETURN NEW; END; $$; CREATE TRIGGER reapply_campaign_rules AFTER INSERT OR UPDATE ON public.lead_campaign_rules FOR EACH ROW EXECUTE FUNCTION public.reapply_lead_campaign_rules();